-- 중독백과 행동중독 17개 본문(body)·심화(advanced) 주입
-- definition(요약)은 건드리지 않고 body/advanced만 갱신. id 기준 UPDATE.
-- 실행: psql -h localhost -U postgres -d addiction_news -f inject_behavioral.sql
BEGIN;
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "행동중독은 술이나 약물 같은 물질 없이도 특정 행동—도박, 게임, 쇼핑, 성, 인터넷 사용—을 스스로 통제하지 못하고 반복하는 상태를 말한다. 핵심은 행동의 종류가 아니라 ''통제력 상실''이다. 즐기던 활동이 어느 순간 하지 않으면 불안하고, 해가 되는 줄 알면서도 멈추지 못하는 단계로 넘어가면 중독의 영역에 들어선다."}, {"h": "물질중독과 무엇이 같은가", "p": "행동중독은 물질중독과 놀랄 만큼 닮았다. 같은 행동에서 점점 더 강한 자극을 필요로 하고(내성), 멈추면 초조·불안을 느끼며(금단 유사 반응), 끊으려 해도 반복하고(재발), 그 과정에서 뇌의 보상회로가 관여한다. 이 유사성이 축적되면서, 중독 개념은 물질을 넘어 행동으로 확장되었다."}, {"h": "어디까지가 중독인가", "p": "모든 몰입이 중독은 아니다. 좋아서 열중하는 것과 통제력을 잃고 삶이 무너지는 것은 다르다. 판단 기준은 ''얼마나 하느냐''가 아니라 기능 손상—일, 관계, 건강, 재정이 실제로 무너지는가, 그리고 스스로 멈출 수 있는가다. 이 기준 때문에 같은 시간을 써도 누군가는 취미이고 누군가는 장애다."}, {"h": "어떻게 볼 것인가", "p": "행동중독은 개인의 의지 문제로 환원하기 어렵다. 뇌의 보상 학습, 스트레스 대처의 실패, 그리고 그 행동을 설계·유도하는 환경(앱·산업)이 함께 작동한다. 그래서 회복도 개인의 결심만이 아니라, 대안적 대처와 환경 조정, 지지 관계가 함께 필요하다."}]'::jsonb, advanced='[{"h": "진단적 지위와 경계", "p": "현재 공식 진단으로 인정된 행동중독은 도박장애(DSM-5·ICD-11)와 게임장애(ICD-11)뿐이다. 쇼핑·성·인터넷·음식 등은 임상·연구에서 다뤄지지만 독립 진단으로 확립되지 않았다. 이는 ''무엇이든 지나치면 중독''이라는 개념 인플레이션을 경계하려는 학계의 신중함을 반영한다. 어디까지를 질환으로 규정할지는 여전히 활발한 논쟁 지점이다."}, {"h": "공통 기전과 논쟁", "p": "행동중독은 보상 예측·인센티브 현저성, 충동성에서 강박성으로의 이동(이중과정), 부적 강화(고통 회피)로 설명된다. 다만 물질과 동일한 신경적 손상을 말할 수 있는지, 아니면 유사한 학습 패턴에 그치는지에 대해 이견이 있다. 과잉 병리화가 정상적 열정까지 질환으로 만들 위험이라는 비판도 함께 존재한다."}, {"h": "당사자·사회적 관점", "p": "행동중독의 상당수는 ''몰래'' 진행되어 신체 흔적이 없고 사회적으로 용인되는 외피(투자, 성실, 취미)를 쓰기 쉽다. 이 때문에 당사자도 문제를 늦게 인정하고, 주변도 알아채기 어렵다. 동시에 관심경제·사행산업처럼 그 행동을 반복하도록 설계된 환경의 책임을 개인 병리로만 돌려선 안 된다는 시각이 커지고 있다."}]'::jsonb, updated_at=now() WHERE id='behavioral-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "도박장애는 해로운 결과가 분명한데도 도박을 멈추지 못하고 반복하는 상태다. 단순히 돈을 많이 잃는 것이 문제가 아니라, 도박에 대한 통제력을 잃고 삶의 다른 영역—일, 관계, 건강, 재정—이 무너지는데도 계속하게 된다는 점이 핵심이다. 오락으로서의 도박과 장애로서의 도박을 가르는 기준은 ''얼마를 걸었나''가 아니라 ''스스로 멈출 수 있는가''다."}, {"h": "어떻게 진행되는가", "p": "많은 경우 처음에는 재미나 스트레스 해소로 시작한다. 초기에 큰 승리를 경험하면 그 기억이 강하게 각인되고, 점차 같은 흥분을 얻기 위해 판돈을 키우게 된다(내성). 잃기 시작하면 ''한 번만 더 하면 만회할 수 있다''는 생각으로 더 크게 거는 추격매수에 빠지고, 이것이 손실을 눈덩이처럼 불린다. 도박을 줄이거나 멈추려 하면 초조·불안을 느끼며, 자금을 마련하고 문제를 숨기기 위해 거짓말과 빚이 쌓이면서 관계와 신뢰가 무너진다."}, {"h": "왜 끊기 어려운가", "p": "도박의 보상은 ''언제 올지 모르게'' 주어진다. 이런 불규칙한 보상 구조는 뇌의 보상회로를 가장 강력하게 학습시키는 방식이어서, 잃는 중에도 ''다음엔 딸지 모른다''는 기대가 행동을 지속시킨다. 특히 돈을 딸 때보다 ''딸 수도 있다''는 불확실한 기대의 순간에 도파민 반응이 커진다는 점이 도박의 중독성을 설명한다. 온라인·모바일 도박은 24시간 즉시 반복이 가능하고 손실이 화면 속 숫자로만 보여, 이 과정을 훨씬 빠르게 만든다."}, {"h": "회복은 가능한가", "p": "가능하다. 도박장애는 만성·재발성 질환으로 이해되며, 재발은 실패가 아니라 회복 과정의 일부로 다뤄진다. 인지행동치료, 동기강화상담, 단도박 모임(GA) 같은 자조 공동체, 재정·법률 문제 정리, 가족의 회복이 함께 작동할 때 효과가 크다. 문제를 인정하는 것—부정을 넘어서는 것—이 회복의 첫 관문이며, 혼자가 아니라 지지 관계 속에서 이뤄질 때 지속된다."}]'::jsonb, advanced='[{"h": "진단 분류의 역사적 전환", "p": "도박장애는 DSM-IV까지 ''병적 도박''으로 충동조절장애에 속했으나, DSM-5(2013)에서 ''물질관련 및 중독장애'' 범주로 이동하며 최초로 공식 인정된 비물질 중독이 되었다. 이는 행동이 물질과 유사한 보상회로 기전·경과·치료 반응을 보인다는 근거가 축적된 결과다. ICD-11 역시 ''중독행동에 의한 장애''로 게임장애와 나란히 분류한다. 이 전환은 이후 게임·인터넷 등 다른 행동중독 논의의 문을 열었다."}, {"h": "이론적 관점과 논쟁", "p": "도박장애는 충동성 주도(초기)에서 강박성 주도(후기)로 이동하는 이중과정 모델, 보상 예측 오류와 인센티브 현저성으로 설명되며, 인지적으로는 통제 착각·도박사의 오류 같은 왜곡된 신념이 유지 요인으로 지목된다. 한편 이를 ''질병''으로 볼 것인가, 학습된·맥락적 행동으로 볼 것인가를 둘러싼 관점 차이가 존재하며, 사행산업의 설계(가변보상·근접실패 연출)가 개인 병리 못지않은 환경적 원인이라는 비판적 시각도 있다."}, {"h": "당사자·회복 관점", "p": "회복 현장의 관점에서 도박장애의 핵심 고통은 돈의 손실보다 자기 통제감과 신뢰의 붕괴에 있다. 추격매수는 종종 손실 자체보다 ''무너진 자기 이미지를 되돌리려는'' 심리로 작동하며, 이 때문에 재정 정리만으로는 회복이 완결되지 않고 관계·의미·자기효능감의 재건이 함께 필요하다. 회복자본—지지 공동체, 안정적 일상, 신뢰 관계—의 두께가 재발 여부를 크게 좌우한다."}]'::jsonb, updated_at=now() WHERE id='pathological-gambling';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "게임이용장애는 게임에 대한 통제력을 잃고, 다른 활동보다 게임을 우선시하며, 부정적 결과가 나타나는데도 계속하거나 오히려 몰입을 키우는 상태를 말한다. 통상 12개월 이상 지속되고 일상 기능에 뚜렷한 손상이 있을 때 진단을 고려한다. 대부분의 게이머는 여기에 해당하지 않으며, 문제의 핵심은 ''많이 하는 것''이 아니라 ''통제력과 기능 손상''이다."}, {"h": "어떻게 진행되는가", "p": "게임은 명확한 목표, 즉각적 보상, 성취감, 사회적 연결을 촘촘하게 제공한다. 현실에서 얻기 어려운 유능감과 소속감을 게임이 채워줄 때, 몰입은 점차 도피와 강박으로 기운다. 수면·식사·학업·일을 미루면서까지 게임을 우선하게 되고, 줄이려 하면 불안·짜증을 느끼며, 관계 갈등과 성적·업무 저하가 뒤따른다."}, {"h": "왜 문제인가", "p": "게임 자체가 나쁜 것이 아니라, 통제 불능이 될 때 문제가 된다. 특히 성장기 청소년의 경우 수면·학업·대인관계가 함께 무너지면 발달에 영향을 줄 수 있다. 게임 안의 확률형 아이템처럼 도박적 요소가 결합되면 위험이 커진다. 반대로 건강한 게임 이용은 스트레스 해소와 사회적 연결의 순기능도 갖는다는 점을 함께 봐야 한다."}, {"h": "대응과 회복", "p": "회복은 게임을 무조건 끊는 것이 아니라 통제력을 되찾는 데 초점을 둔다. 시간·상황을 스스로 관리하는 기술, 게임이 대신 채워주던 욕구(유능감·소속감)를 현실에서 회복하는 것, 공존하는 우울·불안·ADHD를 함께 다루는 것이 중요하다. 청소년의 경우 처벌·차단 일변도보다 가족의 이해와 대안 활동이 효과적이다."}]'::jsonb, advanced='[{"h": "진단을 둘러싼 국제적 차이", "p": "게임장애는 ICD-11에 정식 진단으로 등재됐으나, DSM-5-TR은 ''인터넷게임장애''를 추가 연구가 필요한 상태로 부록에 둔다. 이 차이는 근거의 충분성, 정상적 여가의 병리화 우려, 문화·산업적 이해관계가 얽힌 결과다. 진단 기준의 민감도·특이도, 유병률 추정의 편차도 계속 논의되고 있다."}, {"h": "위험요인과 공존질환", "p": "게임장애는 단독으로 오기보다 우울·불안·ADHD·사회불안과 흔히 공존한다. 이 때문에 게임이 원인인지 결과인지—고통을 게임으로 달래는 자가치료인지—를 구분하는 것이 임상적으로 중요하다. 확률형 아이템 등 도박적 수익모델과의 결합은 게임장애와 도박장애의 경계를 흐리는 새로운 위험으로 지목된다."}, {"h": "사회·산업적 맥락", "p": "게임은 설계 단계에서 몰입을 극대화하도록 정교하게 만들어진다(가변보상, 진행 잠금, 사회적 압박 기제). 따라서 개인의 자제력만 강조하는 접근은 한계가 있으며, 이용자 보호 설계와 규제의 역할이 함께 논의된다. 한국은 게임 산업과 보건 정책이 첨예하게 맞물려, 질병코드 도입을 둘러싼 사회적 논쟁이 특히 두드러진 사례다."}]'::jsonb, updated_at=now() WHERE id='gaming-disorder';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "강박적 컴퓨터·인터넷 사용은 온라인 활동을 통제하지 못해 일상 기능이 손상되는 상태를 포괄적으로 가리킨다. 초기에는 ''인터넷 중독''이라는 단일 개념으로 논의됐지만, 지금은 인터넷 자체가 아니라 그 위에서 무엇을 하느냐—게임, 소셜미디어, 포르노, 쇼핑—가 문제의 본질이라는 관점이 우세하다."}, {"h": "왜 단일 개념에서 멀어졌나", "p": "인터넷은 도구일 뿐이고, 실제 통제력을 잃는 대상은 특정 활동이다. 같은 시간을 온라인에서 보내도 누군가는 업무이고 누군가는 강박적 게임이다. 그래서 ''인터넷을 너무 많이 쓴다''는 뭉뚱그린 진단보다, 어떤 활동에서 통제력을 잃는지를 특정하는 것이 정확하고 치료에도 유리하다."}, {"h": "어떻게 나타나는가", "p": "계획한 시간을 훌쩍 넘겨 사용하고, 줄이려는 시도가 반복 실패하며, 온라인에서 벗어나면 초조해지고, 수면·학업·업무·대면 관계가 밀려난다. 특정 활동(게임·소셜미디어 등)에 대한 갈망이 일상 곳곳에서 촉발된다."}, {"h": "대응", "p": "핵심은 ''무엇에'' 통제력을 잃는지 특정한 뒤 그 활동을 겨냥하는 것이다. 사용 시간·상황의 자기관리, 알림·접근성 조정, 그 활동이 대신 채워주던 정서적 욕구의 대안 마련, 공존하는 우울·불안 관리가 함께 간다."}]'::jsonb, advanced='[{"h": "개념사와 분류", "p": "''인터넷 중독''은 1990년대에 제안됐으나, 이질적 활동을 하나로 묶는다는 비판을 받으며 활동별 세분화로 이동했다. 현재 공식 진단은 게임장애에 국한되고, 소셜미디어·포르노 등은 연구 단계다. 인터넷을 매개로 한 여러 문제를 하나의 장애로 볼지, 각각의 행동중독으로 볼지가 핵심 쟁점이다."}, {"h": "매개인가 대상인가", "p": "논쟁의 축은 인터넷이 ''중독의 대상''인지 ''접근을 매개하는 통로''인지다. 후자의 관점에서 인터넷은 도박·성·쇼핑 등 기존 행동중독의 접근성과 강도를 극적으로 높인 촉진자이며, 문제의 실체는 그 아래의 활동에 있다."}, {"h": "측정과 과잉진단의 위험", "p": "자기보고 척도들이 ''사용량''과 ''장애''를 충분히 구분하지 못해 유병률이 부풀려질 수 있다는 지적이 있다. 디지털 사용이 일상의 기본값이 된 시대에, 정상적 이용과 병리를 가르는 기준(기능 손상·통제력)을 엄격히 적용하는 것이 과잉진단을 막는 관건이다."}]'::jsonb, updated_at=now() WHERE id='compulsive-computer-use';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "소셜미디어 중독은 소셜 플랫폼을 강박적으로 확인·이용하며 통제하지 못해 일상과 정신건강에 해를 끼치는 상태를 말한다. 공식 진단은 아니지만, 알림·무한 스크롤·좋아요·간헐적 보상 같은 ''관심경제''의 설계가 뇌의 보상 시스템을 겨냥한다는 점에서 광범위하게 연구된다."}, {"h": "어떻게 작동하는가", "p": "소셜미디어는 예측 불가능한 보상(누가 반응했을지 모름)과 사회적 인정(좋아요·팔로워)을 결합해, 확인 행동을 반복하도록 강화한다. 무한 스크롤은 멈출 지점을 없애고, 알림은 주의를 끊임없이 끌어당긴다. 그 결과 ''잠깐 확인''이 긴 시간으로 늘어나고, 놓침에 대한 두려움(FOMO)이 재접속을 부른다."}, {"h": "왜 문제인가", "p": "과도한 사용은 수면·집중·대면 관계를 잠식한다. 특히 타인의 편집된 삶과 자신을 비교하는 사회적 비교는 불안·우울·자존감 저하와 연결되며, 청소년기 정신건강과의 관련이 큰 쟁점이다. 연결을 위한 도구가 오히려 고립감과 비교의 원천이 되는 역설이 핵심이다."}, {"h": "대응", "p": "완전한 단절보다 관계를 되찾는 사용이 목표다. 알림 끄기·사용 시간 관리·특정 시간대 차단 같은 환경 조정, 무의식적 확인 습관을 알아차리는 훈련, 대면 관계와 오프라인 활동의 회복이 도움이 된다. 소셜미디어가 채워주던 인정·소속 욕구를 다른 곳에서 건강하게 충족하는 것이 근본 대응이다."}]'::jsonb, advanced='[{"h": "진단적 지위와 측정", "p": "소셜미디어 중독은 표준 진단체계에 등재돼 있지 않고, 여러 자기보고 척도로 연구된다. ''문제적 사용''과 ''중독''을 구분하는 기준, 사용량과 기능 손상의 관계가 계속 논의되며, 도구의 이질성 때문에 유병률 추정이 크게 흔들린다."}, {"h": "인과의 방향 논쟁", "p": "소셜미디어 사용과 청소년 정신건강 악화의 상관은 반복 관찰되지만, 인과의 방향과 크기는 논쟁적이다. 사용이 우울을 유발하는지, 우울한 사람이 더 사용하는지, 제3의 요인이 둘을 함께 설명하는지가 미해결이며, 효과크기가 과장됐다는 반론도 있다."}, {"h": "관심경제와 설계 책임", "p": "플랫폼은 체류시간을 극대화하도록 설계되며, 이 설계가 취약한 사용자에게 미치는 영향에 대한 책임 논의가 커지고 있다. 개인의 절제만 강조하는 관점을 넘어, 이용자 보호 설계·투명성·연령 정책 같은 구조적 대응이 정책 의제로 부상하고 있다."}]'::jsonb, updated_at=now() WHERE id='social-media-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "숏폼·도파민 문화는 짧은 영상의 끝없는 자동재생과 알고리즘 추천이 즉각적 보상을 반복 제공해 강박적 시청을 유도하는 현상을 가리킨다. 임상 진단이라기보다, 주의력과 시간 사용에 영향을 주는 문화·행동 현상으로 이해하는 것이 정확하다."}, {"h": "어떻게 작동하는가", "p": "한 편이 끝나기 전에 다음 편이 자동으로 이어지고, 알고리즘은 사용자의 반응을 학습해 점점 더 붙잡아 두는 영상을 내놓는다. 각 클립은 짧고 강한 자극을 즉시 주기 때문에, ''조금만''이 긴 시간으로 늘어난다. ''도파민''은 이 즉각 보상 루프를 가리키는 대중적 표현으로 쓰인다."}, {"h": "왜 이야기되는가", "p": "짧고 강한 자극에 익숙해지면 길고 느린 몰입—독서, 깊은 대화, 공부—이 상대적으로 지루하게 느껴질 수 있다는 우려가 있다. 시청 후의 허탈감과 집중력 저하가 흔히 보고된다. 다만 이를 임상적 ''중독''으로 단정하기보다 습관·주의력의 문제로 보는 것이 신중하다."}, {"h": "대응", "p": "자동재생 끄기, 시청 시간 정하기, 무의식적 스크롤을 알아차리기 같은 작은 환경·습관 조정이 효과적이다. ''도파민 단식'' 같은 대중 담론이 등장했으나 과학적 근거는 느슨하므로, 자극을 없애기보다 균형을 회복하는 관점이 현실적이다."}]'::jsonb, advanced='[{"h": "과학적 표현으로서의 ''도파민''", "p": "대중적으로 쓰이는 ''도파민 중독'', ''도파민 단식''은 신경과학적으로 부정확한 단순화다. 도파민은 쾌락 그 자체보다 보상 예측·동기·현저성에 관여하며, 특정 활동을 끊는다고 ''도파민이 리셋''되지는 않는다. 개념의 대중적 확산과 과학적 실체 사이의 간극이 이 주제의 특징이다."}, {"h": "주의력·인지에 대한 근거", "p": "짧은 영상의 과다 소비가 지속적 주의력·지연만족·학습에 미치는 영향은 연구가 진행 중이며, 결론은 아직 확정적이지 않다. 상관 연구가 많고 인과·장기 효과의 근거는 제한적이어서, 강한 단정보다 신중한 해석이 요구된다."}, {"h": "설계와 자율성", "p": "자동재생과 추천 알고리즘은 사용자의 멈춤 결정을 어렵게 만들도록 설계된다. 따라서 이 현상은 개인의 의지 문제라기보다, 설계와 개인 습관의 상호작용으로 보는 것이 타당하다. 이용자에게 통제권을 돌려주는 설계(자동재생 기본 해제 등)가 대안으로 논의된다."}]'::jsonb, updated_at=now() WHERE id='short-form-video';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "스마트폰 과의존은 스마트폰 사용을 통제하지 못해 일상·수면·관계·안전이 손상되는 상태를 말한다. 기기 자체보다 그 안의 게임·소셜미디어·영상 등 특정 활동이 문제의 핵심이라는 견해가 우세하다."}, {"h": "어떻게 나타나는가", "p": "이유 없이 반복해서 화면을 확인하고, 대화·식사·심지어 운전 중에도 폰을 놓지 못하며, 알림에 즉각 반응한다. 기기와 떨어지면 불안을 느끼는 노모포비아가 동반되기도 한다. 잠들기 직전과 깨어나자마자 폰을 드는 습관이 수면을 잠식한다."}, {"h": "왜 문제인가", "p": "끊임없는 확인은 주의를 분산시켜 집중과 생산성을 떨어뜨리고, 수면의 질을 해친다. 대면 상황에서도 폰에 주의가 쏠려 관계의 질이 낮아진다. 운전 중 사용처럼 안전과 직결되는 위험도 있다. 기기가 삶을 돕는 도구에서 삶을 지배하는 대상으로 역전되는 것이 문제의 본질이다."}, {"h": "대응", "p": "''무엇에'' 통제력을 잃는지 특정하고 그 앱을 겨냥하는 것이 우선이다. 알림 최소화, 특정 시간·장소에서 기기 분리(식탁·침실 반입 금지), 화면 사용 시간 점검, 대안 활동 마련이 도움이 된다. 기기 탓만 하기보다 그 안의 활동과 그것이 채워주던 욕구를 다루는 것이 핵심이다."}]'::jsonb, advanced='[{"h": "''기기''가 아니라 ''활동''", "p": "연구들은 스마트폰 자체가 아니라 그 위의 특정 활동(소셜미디어·게임·영상)이 문제의 실체임을 시사한다. 따라서 ''스마트폰 중독''이라는 표현은 편의적이며, 실제 개입은 활동 단위로 이뤄져야 효과적이다."}, {"h": "측정과 개념의 한계", "p": "스마트폰 과의존 척도들은 사용량과 병리를 충분히 분리하지 못한다는 비판을 받는다. 스마트폰이 업무·관계·생활의 필수 도구가 된 시대에, 무엇을 ''과의존''으로 볼지의 기준 설정이 까다롭다."}, {"h": "노모포비아와 불안", "p": "기기와 분리될 때의 불안(노모포비아)은 그 자체가 독립 장애라기보다, 연결·정보·안전에 대한 의존과 기저 불안이 스마트폰을 매개로 드러난 것으로 이해된다. 이 관점은 기기 통제보다 기저 욕구·불안을 다루는 접근을 시사한다."}]'::jsonb, updated_at=now() WHERE id='smartphone-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "온라인·모바일 도박은 인터넷과 앱을 통한 도박으로, 24시간 접근성, 실시간 인플레이 베팅, 스포츠 베팅의 급성장이 특징이다. 물리적 도박장에 가지 않아도 손안에서 즉시, 반복해서 베팅할 수 있다는 점이 전통적 도박과 결정적으로 다르다."}, {"h": "무엇이 더 위험한가", "p": "접근 장벽이 사라지면서 충동과 실행 사이의 간격이 없어진다. 24시간 언제든, 얼마든지 반복할 수 있고, 손실이 실제 현금이 아니라 화면 속 숫자로만 보여 잃는다는 실감이 둔해진다. 실시간 베팅은 경기를 보는 내내 반복 배팅을 유도한다. 이 요소들이 위험 도박으로의 전환을 훨씬 빠르게 만든다."}, {"h": "어떻게 진행되는가", "p": "가벼운 재미로 시작해도 즉시·반복 가능한 구조가 통제력을 빠르게 무너뜨린다. 추격매수가 오프라인보다 쉽게 일어나고, 손실을 숨기기 쉬워 문제가 늦게 드러난다. 스마트폰만 있으면 언제 어디서든 가능해, 일상 전반으로 스며든다."}, {"h": "대응", "p": "접근 차단(자가 배제 프로그램, 결제·앱 제한)이 오프라인보다 더 중요하다. 도박장애 일반의 회복 원리—인지행동치료, 자조 모임, 재정 정리, 지지 관계—가 동일하게 적용되며, 24시간 접근을 물리적으로 끊는 장치가 특히 유효하다."}]'::jsonb, advanced='[{"h": "구조적 위험 요인", "p": "온라인 도박의 위험은 개인 성향뿐 아니라 매체 구조에서 나온다. 무제한 접근성, 빠른 베팅 주기, 인플레이·마이크로베팅, 손실의 추상화(디지털 잔액)가 결합해 통제 상실을 가속한다. 이는 ''어떤 매체로 하느냐''가 위험도를 좌우함을 보여준다."}, {"h": "규제와 광고", "p": "각국은 온라인 도박 광고, 접근 시간, 베팅 한도, 자가 배제 제도를 강화하는 추세다. 특히 스포츠 베팅 광고의 급증과 청소년 노출이 정책 쟁점이다. 합법·불법 시장의 경계, 국경을 넘는 서비스가 규제를 어렵게 만든다."}, {"h": "디지털 흔적과 개입 가능성", "p": "역설적으로 온라인 도박은 베팅 데이터를 남기기 때문에, 위험 패턴을 조기 탐지하고 개입할 여지도 크다. 사업자에게 위험 신호 모니터링·개입 의무를 부과하는 ''책임 도박'' 설계가 논의되지만, 수익 구조와의 이해충돌이 한계로 지적된다."}]'::jsonb, updated_at=now() WHERE id='online-gambling';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "확률형 아이템(루트박스)은 게임 안에서 무작위 보상을 얻기 위해 결제하는 상품이다. 무엇이 나올지 모른 채 돈을 지불한다는 점에서, 결과의 불확실성과 보상 구조가 도박과 매우 유사하다."}, {"h": "왜 도박과 닮았나", "p": "루트박스는 ''언제 원하는 것이 나올지 모르는'' 가변보상 구조를 그대로 담고 있다. 이것은 도박의 중독성을 만드는 핵심 원리와 같다. 원하는 아이템이 나올 때까지 반복 결제하게 되고, ''조금만 더 하면''이라는 심리가 지출을 키운다. 게임과 도박의 경계가 흐려지는 지점이다."}, {"h": "왜 문제인가", "p": "특히 청소년이 쉽게 접근한다는 점이 큰 우려다. 도박이라는 인식 없이 게임 속 결제로 도박적 행동을 학습하게 될 수 있고, 예상보다 큰 금액을 지출하는 사례가 발생한다. 재미 요소로 포장돼 있어 문제로 인식되기 어렵다."}, {"h": "대응과 규제", "p": "일부 국가는 루트박스를 규제하거나 사실상 도박으로 분류했다. 확률 공개 의무, 연령 제한, 지출 한도 같은 이용자 보호 장치가 논의된다. 보호자 입장에서는 결제 제한과 확률형 아이템의 도박적 성격을 아이가 이해하도록 돕는 것이 필요하다."}]'::jsonb, advanced='[{"h": "게임-도박 융합의 최전선", "p": "루트박스는 게임장애와 도박장애의 경계를 흐리는 대표 사례다. 연구들은 루트박스 지출과 문제 도박 사이의 상관을 보고하며, 이것이 청소년에게 도박적 인지·행동을 조기 학습시키는 ''관문'' 역할을 하는지가 쟁점이다."}, {"h": "규제의 딜레마", "p": "루트박스를 도박으로 규정할지는 국가마다 갈린다. ''실제 화폐로 환전 가능한가'', ''결과가 순전히 운인가'' 등 도박의 법적 정의를 어떻게 적용하느냐에 따라 판단이 달라진다. 산업의 핵심 수익모델이라는 점이 규제를 복잡하게 만든다."}, {"h": "설계 윤리", "p": "루트박스는 근접실패 연출, 획득 순간의 화려한 연출, 한정 판매 등 심리적 장치를 동원한다. 이런 설계가 특히 미성숙한 이용자의 충동을 겨냥한다는 점에서, 개인 책임을 넘어 설계 윤리와 이용자 보호의 문제로 다뤄진다."}]'::jsonb, updated_at=now() WHERE id='loot-boxes';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "암호화폐·투자 중독은 암호화폐나 주식 등의 고빈도 거래를 도박과 유사한 방식으로 강박적으로 반복하는 행동 패턴을 말한다. 투자라는 정당한 외피를 쓰고 있어 문제 인식이 늦어지기 쉽다."}, {"h": "어떻게 진행되는가", "p": "24시간 열린 시장과 극심한 변동성이 끊임없는 확인과 거래를 부른다. 큰 수익의 짜릿함이 각인되면 점점 더 큰 위험을 감수하게 되고, 손실이 나면 만회하려 더 크게 베팅하는 추격매매에 빠진다. 시세 창을 밤새 확인하고, 일상과 수면이 거래 리듬에 지배당한다."}, {"h": "왜 도박에 가까운가", "p": "단기 고빈도 매매는 분석보다 즉각적 흥분과 요행에 기대는 경우가 많아, 구조적으로 도박에 가깝다. 거래를 게임처럼 만드는 앱 설계(간편한 원터치 매매, 알림, 축하 연출)가 충동을 부추긴다. 흔히 도박장애의 틀로 이해된다."}, {"h": "대응", "p": "''투자''와 ''강박적 거래''를 구분하는 것이 첫걸음이다. 거래 빈도·금액의 한계 설정, 실시간 알림·앱 접근 제한, 손실 만회 심리의 자각, 그리고 도박장애 회복 원리(자조 모임·재정 정리·지지 관계)가 동일하게 적용된다."}]'::jsonb, advanced='[{"h": "투자와 병리의 경계", "p": "모든 적극적 거래가 중독은 아니다. 계획적 투자와, 통제력을 잃고 삶이 무너지는 강박적 거래를 가르는 기준은 역시 통제력과 기능 손상이다. ''투자''라는 사회적 정당성이 병리의 인식을 지연시키는 것이 이 영역의 특수성이다."}, {"h": "구조적 촉진 요인", "p": "24시간 시장, 무한 변동성, 레버리지, 게임화된 거래 인터페이스, 소셜미디어의 ''떡상'' 서사가 결합해 충동적 거래를 부추긴다. 이는 개인 성향만이 아니라 시장·플랫폼 구조가 위험을 키운다는 점을 보여준다."}, {"h": "연구의 초기 단계", "p": "암호화폐·투자 중독은 독립 진단이 아니며, 도박장애의 하위 양상 또는 인접 현상으로 연구되는 초기 단계다. 표준 척도와 유병률 데이터가 부족해, 도박장애 연구의 틀을 빌려 접근하는 경우가 많다."}]'::jsonb, updated_at=now() WHERE id='crypto-trading-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "강박적 쇼핑은 구매 충동을 통제하지 못해 필요 이상으로 반복 소비하고, 그 결과 재정적·정서적 고통을 겪는 행동 패턴이다. 공식 진단으로 확립되진 않았으나 충동조절·중독 스펙트럼에서 논의된다."}, {"h": "어떻게 나타나는가", "p": "구매 전에는 긴장과 갈망이 고조되고, 구매하는 순간 안도와 쾌감을 느끼지만, 곧 후회와 죄책감이 뒤따르는 순환이 반복된다. 필요해서가 아니라 감정을 달래기 위해 사고, 산 물건을 제대로 쓰지 않거나 숨기기도 한다."}, {"h": "왜 문제인가", "p": "충동적 소비가 빚과 재정 파탄으로 이어지고, 그로 인한 수치심과 관계 갈등이 다시 소비를 부르는 악순환을 만든다. 모바일·라이브 커머스의 확산으로 언제 어디서든 즉시 구매가 가능해지면서 접근성과 위험이 크게 높아졌다."}, {"h": "대응", "p": "소비가 어떤 감정(공허·불안·우울)을 달래려는 것인지 알아차리는 것이 핵심이다. 결제 수단·쇼핑 앱 접근 제한, 구매 전 대기 시간 두기, 대안적 정서 조절 방법 마련, 공존하는 우울·불안 관리가 함께 간다."}]'::jsonb, advanced='[{"h": "진단적 지위", "p": "강박적 구매는 DSM·ICD의 독립 진단이 아니다. 충동조절장애, 행동중독, 우울·불안의 이차 증상 등 어디에 위치시킬지에 대한 견해가 갈린다. 이 모호함이 임상적 개입과 연구를 어렵게 하는 요인이다."}, {"h": "정서 조절 가설", "p": "강박적 쇼핑은 흔히 부정적 정서를 완화하려는 자가치료적 행동으로 이해된다. 구매의 쾌감이 일시적으로 기분을 끌어올리지만 곧 죄책감으로 반전되며, 이 정서 순환이 반복을 강화한다. 그래서 소비 억제보다 기저 정서를 다루는 접근이 강조된다."}, {"h": "소비 환경의 역할", "p": "라이브·모바일 커머스, 초개인화 추천, 원클릭 결제, 무이자 할부는 충동과 구매 사이의 마찰을 없앤다. 강박적 쇼핑을 개인 성향만의 문제로 보기 어렵게 만드는, 소비를 극대화하도록 설계된 환경의 역할이 커지고 있다."}]'::jsonb, updated_at=now() WHERE id='compulsive-shopping';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "성중독은 성적 사고·충동·행동을 통제하지 못해 반복하며 개인의 기능과 관계에 해를 끼치는 상태를 말한다. 도덕적 판단과 병리를 구분해 신중하게 접근해야 하는 영역이다."}, {"h": "어떻게 구분하는가", "p": "핵심은 성적 행동의 빈도나 종류가 아니라 통제력 상실과 그로 인한 실질적 해다. 반복되는 성적 행동이 관계·직업·건강에 분명한 손상을 주는데도 스스로 멈추지 못하고, 그 때문에 고통받을 때 문제가 된다. 개인의 가치관·문화와 병리를 혼동하지 않는 것이 중요하다."}, {"h": "무엇이 얽히는가", "p": "성중독은 흔히 정서적 고통, 외로움, 트라우마, 우울·불안과 얽혀 있으며, 성적 행동이 그 고통을 달래는 통로로 작동하기도 한다. 수치심이 커서 도움을 요청하기 어렵고, 이 침묵이 문제를 지속시킨다."}, {"h": "대응", "p": "낙인 없는 이해와 전문적 도움이 필요하다. 기저의 정서적 고통·트라우마를 함께 다루는 치료, 강박적 행동의 방아쇠를 관리하는 기술, 건강한 친밀감의 회복이 목표가 된다. 파트너·관계를 포함한 접근이 도움이 되는 경우가 많다."}]'::jsonb, advanced='[{"h": "진단 분류와 명칭 논쟁", "p": "ICD-11은 이를 ''강박적 성행동장애''로서 충동조절장애에 분류하며, 이를 ''중독''으로 부를지에 대해 학계 견해가 갈린다. ''성중독''이라는 명칭이 병리화·낙인을 조장한다는 비판과, 임상 현실을 반영한다는 옹호가 맞선다."}, {"h": "도덕·문화와의 경계", "p": "성적 행동에 대한 판단은 문화·가치관에 크게 좌우되므로, 무엇을 ''과도''로 볼지 자체가 논쟁적이다. 종교적·도덕적 죄책감이 실제 통제 상실과 혼동될 위험이 있어, 진단은 문화적 규범이 아니라 기능 손상과 통제력을 기준으로 삼아야 한다."}, {"h": "공존과 기저 요인", "p": "강박적 성행동은 트라우마, 애착 손상, 우울·불안과 흔히 공존한다. 이 관점에서 성적 행동은 종종 정서 조절과 애착 결핍을 메우려는 시도로 이해되며, 표면 행동만이 아니라 그 아래의 관계·정서 구조를 다루는 치료가 강조된다."}]'::jsonb, updated_at=now() WHERE id='sexual-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "사이버섹스·포르노 중독은 온라인 성적 콘텐츠나 활동을 강박적으로 소비·이용해 통제력을 잃는 상태를 말한다. 무제한·즉시·익명 접근이라는 인터넷의 특성이 그 핵심 배경이다."}, {"h": "어떻게 진행되는가", "p": "계획한 것보다 훨씬 많은 시간을 성적 콘텐츠에 쓰고, 줄이려는 시도가 반복 실패하며, 점점 더 강한 자극을 찾게 되기도 한다. 일상·수면·관계에 지장이 생기고, 그로 인한 수치심이 다시 도피적 사용을 부른다."}, {"h": "왜 온라인이 다른가", "p": "오프라인과 달리 무한한 콘텐츠에 즉시·익명으로 접근할 수 있다는 점이 통제를 어렵게 한다. 끝없는 새로움이 갈망을 유지시키고, 익명성이 브레이크를 약화시킨다. 잦은 사용이 성적 기대와 반응을 변화시킬 수 있다는 논의도 있다."}, {"h": "대응", "p": "접근 통제(필터·기기 관리), 사용을 촉발하는 정서적 방아쇠의 자각, 기저의 외로움·불안·트라우마 관리, 건강한 친밀감의 회복이 함께 간다. 수치심을 낮추고 도움을 요청할 수 있는 환경이 회복의 전제다."}]'::jsonb, advanced='[{"h": "진단적 지위와 근거", "p": "사이버섹스·포르노 중독은 강박적 성행동장애의 틀 안에서 다뤄지며, 독립 진단으로 확립되진 않았다. ''문제적 포르노 사용''과 병리적 중독을 구분하는 기준, 그리고 근거의 충분성이 계속 논의된다."}, {"h": "도덕적 불일치의 함정", "p": "연구들은 포르노 사용에 대한 ''도덕적 불일치''(자신의 가치관과 행동의 충돌)가 실제 중독과 무관하게 고통과 ''중독감''을 만들 수 있음을 지적한다. 따라서 자기 낙인과 실제 통제 상실을 구분하는 것이 임상적으로 중요하다."}, {"h": "신경·행동 논쟁", "p": "잦은 포르노 사용이 보상 반응·기대를 변화시키는지에 대한 연구가 있으나, 결과는 엇갈리고 인과는 확립되지 않았다. 물질중독과 동일한 신경적 손상을 말할 수 있는지에 대해 신중한 해석이 요구된다."}]'::jsonb, updated_at=now() WHERE id='cybersex-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "과잉성욕은 성적 충동과 활동이 과도하게 항진되어 일상과 관계를 지배하는 상태를 말한다. 강박적 성행동장애의 핵심 특징이지만, 그 원인이 다양하다는 점이 중요하다."}, {"h": "원인은 하나가 아니다", "p": "과잉성욕은 강박적 성행동장애의 일부일 수도 있지만, 일부 신경질환(뇌 손상·치매 등)이나 특정 약물(예: 파킨슨병 치료에 쓰는 도파민 작용제)의 부작용으로도 나타날 수 있다. 조증 삽화의 증상으로 나타나기도 한다. 그래서 원인 감별이 치료의 출발점이다."}, {"h": "왜 감별이 중요한가", "p": "원인에 따라 대응이 전혀 다르기 때문이다. 약물 부작용이라면 약물 조정이, 조증이라면 기분장애 치료가, 강박적 성행동이라면 심리치료가 우선이다. 표면 증상만 보고 하나의 문제로 다루면 정확한 도움을 놓친다."}, {"h": "대응", "p": "먼저 의학적·정신과적 평가로 기저 원인을 확인한다. 신경질환·약물·기분장애가 배경이면 그것을 다루고, 강박적 성행동이면 심리치료와 정서·관계 회복을 병행한다. 낙인 없이 원인을 찾는 접근이 핵심이다."}]'::jsonb, advanced='[{"h": "증상인가 장애인가", "p": "과잉성욕은 그 자체로 독립 진단이라기보다, 여러 상태에서 나타나는 ''증상''으로 이해하는 것이 정확하다. 강박적 성행동장애, 양극성 조증, 신경인지장애, 의인성(약물유발) 등 감별진단의 폭이 넓다."}, {"h": "의인성 과잉성욕", "p": "파킨슨병 등에서 도파민 작용제 치료 중 나타나는 충동조절장애(과잉성욕·병적 도박·강박적 쇼핑 등)는 도파민 보상 회로가 중독 행동에 어떻게 관여하는지를 보여주는 임상적 창이다. 약물 조정으로 호전된다는 점이 원인 감별의 중요성을 강조한다."}, {"h": "평가의 신중함", "p": "성욕의 ''정상'' 범위는 개인·문화 차가 크므로, 과잉성욕 판정은 빈도 자체가 아니라 통제 상실과 기능 손상, 그리고 기저 원인의 존재를 종합해 신중히 이뤄져야 한다."}]'::jsonb, updated_at=now() WHERE id='hypersexuality';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "일중독은 휴식·건강·관계를 희생하면서까지 강박적으로 일에 몰두하고, 일에서 벗어날 때 불안·죄책감을 느끼는 상태를 말한다. 성취 자체가 아니라 통제력을 잃은 강박이 핵심이다."}, {"h": "열정과 무엇이 다른가", "p": "일을 사랑하는 것과 일에 중독된 것은 다르다. 건강한 몰입은 일하지 않을 때 쉴 수 있지만, 일중독은 쉬는 순간 불안하고 죄책감을 느껴 멈추지 못한다. 건강·관계가 무너지는데도 일하는 시간을 줄이지 못하고, 일로 자기 가치를 증명하려 한다."}, {"h": "왜 알아채기 어려운가", "p": "일중독은 사회적으로 칭찬받기 쉽다. 성실·헌신으로 포장되어 본인도 주변도 문제로 보지 않는다. 그러나 그 이면에서 번아웃, 수면·건강 악화, 가족 관계 소외가 진행된다. 사회적 인정이 문제 인식을 지연시키는 것이 이 중독의 특징이다."}, {"h": "대응", "p": "일이 대신 채워주던 것(불안 회피, 자기 가치, 통제감)을 알아차리는 것이 출발점이다. 일과 휴식의 경계 설정, 자기 가치를 성과 밖에서 찾는 연습, 번아웃·불안의 관리, 관계 회복이 함께 간다. 장시간 노동을 미화하는 조직 문화의 영향도 함께 봐야 한다."}]'::jsonb, advanced='[{"h": "진단적 지위와 번아웃과의 관계", "p": "일중독은 공식 진단이 아니며, 번아웃·강박·불안과 겹쳐 논의된다. 번아웃이 소진의 ''결과''라면 일중독은 그 소진을 향해 달리는 ''과정''에 가깝다. 둘의 관계와 경계, 측정 방식이 연구의 쟁점이다."}, {"h": "동기의 이질성", "p": "일중독의 동기는 단일하지 않다. 성취 지향, 완벽주의, 불안 회피, 자존감 보상 등 서로 다른 기저 동기가 유사한 행동으로 나타난다. 이 이질성 때문에 ''일을 많이 한다''는 것만으로는 병리를 규정할 수 없다."}, {"h": "문화·구조적 맥락", "p": "일중독은 개인 성향만이 아니라 장시간 노동을 미덕으로 삼는 문화, 성과주의, 상시 연결 노동 환경에 의해 강화된다. 한국처럼 노동 시간·경쟁 압력이 높은 사회에서 특히 사회적 함의가 크며, 개인 치료를 넘어선 구조적 논의를 요구한다."}]'::jsonb, updated_at=now() WHERE id='work-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "음식중독은 고당·고지방 등 특정 음식에 대한 갈망과 통제 상실적 섭취가 반복되는 상태를 말한다. 물질중독과 유사한 보상회로 관여가 보고되지만, 독립 진단으로 확립되진 않았고 폭식장애 등 섭식장애와 개념적으로 겹친다."}, {"h": "어떻게 나타나는가", "p": "배가 고프지 않은데도 특정 음식(주로 초가공식품)을 통제하지 못하고 계속 먹고, 그 뒤 죄책감을 느끼는 순환이 반복된다. 줄이려 해도 실패하고, 특정 음식에 대한 강한 갈망이 스트레스나 감정에 의해 촉발된다."}, {"h": "음식이 설계되는가", "p": "고도로 가공된 식품은 당·지방·염분·식감을 뇌의 보상을 극대화하도록 조합해 만든다는 지적이 있다. 자연 상태의 음식에서는 드문 강한 보상이 반복 섭취를 부추긴다는 것이다. 개인의 절제 문제로만 보기 어렵게 만드는 지점이다."}, {"h": "대응", "p": "''무엇이 방아쇠인지''(특정 음식·감정·상황)를 파악하고, 그 음식과 감정 사이의 연결을 다루는 것이 핵심이다. 극단적 제한은 오히려 폭식을 부를 수 있어 신중해야 하며, 섭식장애가 의심되면 전문적 도움이 필요하다. 감정 조절의 대안을 마련하는 것이 근본 대응이다."}]'::jsonb, advanced='[{"h": "개념과 진단 논쟁", "p": "''음식중독''이 별개의 실체인지, 폭식장애의 다른 표현인지, 아니면 특정 성분(설탕 등)에 대한 중독인지에 대해 논쟁이 계속된다. 예일음식중독척도 같은 도구가 물질중독 기준을 음식에 적용해 측정을 시도하지만, 개념의 타당성 자체가 미결이다."}, {"h": "성분 대 행동", "p": "핵심 논쟁 중 하나는 중독의 대상이 ''설탕 같은 특정 성분''인지 ''먹는 행동''인지다. 동물 연구는 간헐적 당 섭취에서 중독 유사 패턴을 보이기도 하나, 인간에서의 성분 특이적 중독 근거는 아직 논쟁적이다."}, {"h": "섭식장애와의 관계", "p": "음식중독 개념은 폭식장애와 상당 부분 겹친다. 이 때문에 별도의 ''중독''으로 다루는 것이 임상적으로 유용한지, 아니면 낙인을 더하는지에 대한 신중한 검토가 요구된다. 극단적 식이 제한을 조장하지 않는 접근이 특히 중요하다."}]'::jsonb, updated_at=now() WHERE id='food-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "운동중독은 부상·피로·일상 지장에도 강박적으로 운동을 지속하고, 중단 시 금단 유사 증상(불안·초조)을 겪는 상태를 말한다. 건강행동이 병리로 전환되는 대표 사례다."}, {"h": "헌신과 무엇이 다른가", "p": "열심히 운동하는 것과 운동에 중독된 것은 다르다. 건강한 운동은 상황에 따라 쉴 수 있지만, 운동중독은 다쳐서 쉬어야 할 때도 불안 때문에 멈추지 못한다. 운동이 삶을 위한 것이 아니라, 삶이 운동을 중심으로 재편되고 다른 영역이 밀려날 때 문제가 된다."}, {"h": "무엇과 얽히는가", "p": "운동중독은 흔히 섭식장애나 신체상(외모·체형) 문제와 함께 나타난다. 이 경우 운동은 건강이 아니라 체형 통제나 불안 완화의 강박적 수단이 된다. 부상을 무릅쓴 과잉운동은 신체를 오히려 해친다."}, {"h": "대응", "p": "운동을 없애는 것이 아니라 통제력과 균형을 회복하는 것이 목표다. 휴식을 계획에 포함시키고, 운동이 대신 다루던 불안·신체상 문제를 직접 다루며, 섭식장애가 의심되면 함께 평가한다. 운동의 순기능은 살리되 강박에서 벗어나는 것이 핵심이다."}]'::jsonb, advanced='[{"h": "일차성과 이차성", "p": "운동중독은 그 자체가 목적인 ''일차성''과, 섭식장애 등에 동반되어 체중·체형 통제 수단으로 나타나는 ''이차성''으로 구분되기도 한다. 이차성인 경우 근본 문제인 섭식장애를 다루지 않으면 운동 통제만으로는 회복이 어렵다."}, {"h": "진단적 지위", "p": "운동중독은 공식 진단이 아니며, 행동중독의 한 후보로 연구된다. 금단 유사 증상, 내성, 통제 상실 같은 중독 기준을 운동에 적용해 측정하지만, 건강한 고강도 훈련과 병리를 가르는 기준 설정이 까다롭다."}, {"h": "건강 담론과의 긴장", "p": "운동은 사회적으로 권장되는 건강행동이라, 그 병리적 형태는 인식되기 어렵고 오히려 칭찬받기 쉽다. SNS의 운동 인증 문화가 과잉운동과 신체상 강박을 부추길 수 있다는 점에서, 건강 담론과 병리의 경계를 함께 살펴야 한다."}]'::jsonb, updated_at=now() WHERE id='exercise-addiction';
COMMIT;
-- 확인: SELECT id, jsonb_array_length(body) b, jsonb_array_length(advanced) a FROM encyclopedia_terms WHERE category='behavioral' ORDER BY id;   backend/에 파일을 넣고
